        "code": "import json
import urllib.request
import urllib.error

def get_directory_contents(api_url):
    """Recursively fetch directory contents from GitHub API"""
    try:
        with urllib.request.urlopen(api_url) as response:
            return json.loads(response.read().decode())
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise

def build_file_structure(contents, base_path=""):
    """Build file structure tree from API response"""
    structure = []

    if not contents:
        return structure

    for item in contents:
        item_path = f"{base_path}/{item['name']}" if base_path else item['name']

        if item['type'] == 'file':
            structure.append({
                'type': 'file',
                'name': item['name'],
                'path': item_path,
                'size': item.get('size', 0)
            })
        elif item['type'] == 'dir':
            # Get subdirectory contents
            sub_contents = get_directory_contents(item['url'])
            sub_structure = build_file_structure(sub_contents, item_path)

            structure.append({
                'type': 'directory',
                'name': item['name'],
                'path': item_path,
                'children': sub_structure
            })

    return structure

def format_file_structure(structure, indent=0):
    """Format file structure as readable text"""
    result = []
    prefix = "  " * indent

    for item in structure:
        if item['type'] == 'file':
            result.append(f"{prefix}📄 {item['name']}")
        else:  # directory
            result.append(f"{prefix}📁 {item['name']}/")
            if item['children']:
                result.append(format_file_structure(item['children'], indent + 1))

    return "\n".join(result)

def main(initial_response: str):
    """Main function to process GitHub repository structure"""
    try:
        # Parse initial response
        root_contents = json.loads(initial_response)

        # Build complete file structure
        file_structure_tree = build_file_structure(root_contents)

        # Format as readable text
        formatted_structure = format_file_structure(file_structure_tree)

        return {
            "file_structure": formatted_structure
        }
    except json.JSONDecodeError:
        return {
            "file_structure": "Error: Invalid API response format"
        }
    except Exception as e:
